insert into apimanager_api (uuid, name, description, path, active, in_maintenance, wait, openapi, archived, version, status)
values  ('3d061ebc-673f-4592-9de6-f7e2babedc8f', 'api-bot', 'API robot for IA chat', '/api-bot', 0, 0, 0, '{"openapi":"3.0.0","info":{"title":"Bot API","description":"API pour interagir avec des bots, gÃ©rer les conversations et les documents.","version":"1.0.0"},"servers":[{"url":"https://api.example.com/v1"}],"tags":[{"name":"Bots","description":"OpÃ©rations liÃ©es Ã  la gestion des bots."},{"name":"Conversations","description":"Gestion des conversations et de leur historique."},{"name":"Streaming","description":"Initialisation et gestion des flux de donnÃ©es en temps rÃ©el."},{"name":"Documents","description":"Gestion et tÃ©lÃ©chargement de documents."},{"name":"Utilisateurs","description":"OpÃ©rations liÃ©es aux utilisateurs."}],"paths":{"/bots":{"get":{"tags":["Bots"],"summary":"RÃ©cupÃ©rer la liste des bots autorisÃ©s","description":"Renvoie une liste des bots disponibles et autorisÃ©s pour l''utilisateur.","operationId":"getBots","responses":{"200":{"description":"Une liste de bots est retournÃ©e.","content":{"application/json":{"schema":{"type":"array","items":{"$ref":"#/components/schemas/Bot"}}}}}}}},"/query/stream/init":{"post":{"tags":["Streaming"],"summary":"Initialiser une requÃªte en streaming","description":"CrÃ©e un identifiant de flux (streamId) pour une conversation en streaming.","operationId":"initializeStream","requestBody":{"required":true,"content":{"application/json":{"schema":{"type":"object","properties":{"botId":{"type":"string","description":"L''identifiant du bot avec lequel interagir."},"conversation_uuid":{"type":"string","format":"uuid","description":"L''UUID de la conversation existante."},"message":{"type":"string","description":"Le message de l''utilisateur pour initialiser le flux."}}}}}},"responses":{"200":{"description":"Flux initialisÃ© avec succÃ¨s.","content":{"application/json":{"schema":{"$ref":"#/components/schemas/StreamInitResponse"}}}}}}},"/query/stream/events/{streamId}":{"get":{"tags":["Streaming"],"summary":"Ãcouter les Ã©vÃ©nements de streaming (SSE)","description":"Ãcoute les Ã©vÃ©nements Server-Sent Events (SSE) pour un flux spÃ©cifique.","operationId":"listenToStreamEvents","parameters":[{"name":"streamId","in":"path","required":true,"schema":{"type":"string"},"description":"L''identifiant du flux de streaming."}],"responses":{"200":{"description":"Le flux d''Ã©vÃ©nements SSE est ouvert.","content":{"text/event-stream":{"schema":{"type":"string","description":"ÃvÃ©nements de streaming du bot."}}}}}}},"/conversation/{conversation_uuid}":{"post":{"tags":["Conversations"],"summary":"RÃ©cupÃ©rer l''historique d''une conversation","description":"RÃ©cupÃ¨re l''historique complet des messages pour une conversation donnÃ©e.","operationId":"getConversationHistory","parameters":[{"name":"conversation_uuid","in":"path","required":true,"schema":{"type":"string","format":"uuid"},"description":"L''UUID de la conversation."}],"responses":{"200":{"description":"Historique de la conversation retournÃ©.","content":{"application/json":{"schema":{"type":"object","properties":{"messages":{"type":"array","items":{"$ref":"#/components/schemas/Message"}}}}}}}}}},"/user/conversations":{"post":{"tags":["Conversations","Utilisateurs"],"summary":"RÃ©cupÃ©rer toutes les conversations d''un utilisateur","description":"RÃ©cupÃ¨re une liste de toutes les conversations associÃ©es Ã  l''utilisateur authentifiÃ©.","operationId":"getUserConversations","responses":{"200":{"description":"Liste des conversations de l''utilisateur.","content":{"application/json":{"schema":{"type":"array","items":{"$ref":"#/components/schemas/ConversationSummary"}}}}}}}},"/conversation/{conversation_uuid}/delete":{"post":{"tags":["Conversations"],"summary":"Supprimer une conversation","description":"Supprime une conversation spÃ©cifique en utilisant son UUID.","operationId":"deleteConversation","parameters":[{"name":"conversation_uuid","in":"path","required":true,"schema":{"type":"string","format":"uuid"},"description":"L''UUID de la conversation Ã  supprimer."}],"responses":{"204":{"description":"Conversation supprimÃ©e avec succÃ¨s."},"404":{"description":"Conversation introuvable."}}}},"/user/conversations/delete":{"post":{"tags":["Conversations","Utilisateurs"],"summary":"Supprimer toutes les conversations d''un utilisateur","description":"Supprime toutes les conversations associÃ©es Ã  l''utilisateur.","operationId":"deleteAllUserConversations","responses":{"204":{"description":"Toutes les conversations de l''utilisateur ont Ã©tÃ© supprimÃ©es."},"400":{"description":"Erreur lors de la suppression des conversations."}}}},"/user/rate":{"post":{"tags":["Utilisateurs"],"summary":"RÃ©cupÃ©rer les limites de taux d''un utilisateur","description":"Fournit des informations sur les limites de requÃªtes (rate limits) de l''utilisateur.","operationId":"getUserRateLimits","responses":{"200":{"description":"Limites de taux retournÃ©es.","content":{"application/json":{"schema":{"$ref":"#/components/schemas/RateLimit"}}}}}}},"/document/{bot_id}/{dataset_id}/{document_id}":{"get":{"tags":["Documents"],"summary":"TÃ©lÃ©charger un fichier de document","description":"TÃ©lÃ©charge un document spÃ©cifique associÃ© Ã  un bot et un ensemble de donnÃ©es.","operationId":"downloadDocument","parameters":[{"name":"bot_id","in":"path","required":true,"schema":{"type":"string"},"description":"L''identifiant du bot."},{"name":"dataset_id","in":"path","required":true,"schema":{"type":"string"},"description":"L''identifiant de l''ensemble de donnÃ©es."},{"name":"document_id","in":"path","required":true,"schema":{"type":"string"},"description":"L''identifiant du document Ã  tÃ©lÃ©charger."}],"responses":{"200":{"description":"Le document est retournÃ©.","content":{"application/octet-stream":{"schema":{"type":"string","format":"binary"}}}},"404":{"description":"Le document n''a pas Ã©tÃ© trouvÃ©."},"400":{"description":"RequÃªte invalide."}}}}},"components":{"schemas":{"Bot":{"type":"object","properties":{"id":{"type":"string","description":"L''identifiant unique du bot."},"name":{"type":"string","description":"Le nom du bot."},"description":{"type":"string","description":"Une brÃ¨ve description du bot."}}},"Message":{"type":"object","properties":{"sender":{"type":"string","enum":["user","bot"],"description":"L''expÃ©diteur du message."},"text":{"type":"string","description":"Le contenu du message."},"timestamp":{"type":"string","format":"date-time","description":"L''horodatage du message."}}},"ConversationSummary":{"type":"object","properties":{"uuid":{"type":"string","format":"uuid","description":"L''UUID de la conversation."},"title":{"type":"string","description":"Le titre de la conversation."},"lastUpdated":{"type":"string","format":"date-time","description":"La date de la derniÃ¨re mise Ã  jour de la conversation."}}},"StreamInitResponse":{"type":"object","properties":{"streamId":{"type":"string","description":"L''identifiant unique du flux de streaming."}}},"RateLimit":{"type":"object","properties":{"limit":{"type":"integer","description":"Le nombre maximum de requÃªtes autorisÃ©es."},"remaining":{"type":"integer","description":"Le nombre de requÃªtes restantes."},"resetTime":{"type":"string","format":"date-time","description":"Le temps de rÃ©initialisation des limites."}}}},"securitySchemes":{"BearerAuth":{"type":"http","scheme":"bearer","bearerFormat":"JWT"}}},"security":[{"BearerAuth":[]}]}', 0, '1.0', 'NEW');

